# Download, verify, and unpack rokoko-sdk-release 2026.10.20 into $Env:ROKOKO_SDK_HOME.
# Generated by packager; do not edit. Usage: pwsh -File install-device-sdk.ps1
#                                        or: .\install-device-sdk.ps1

[CmdletBinding()]
param()

$ErrorActionPreference = 'Stop'

$Bucket    = 'rokoko-device-sdk'
$Prefix    = 'releases'
$Name      = 'rokoko-sdk-release'
$Version   = '2026.10.20'
$ReleaseId = '2c0a73311fa0eb74'
$Platform  = 'windows'

$Zip     = "$Name-$Platform-$Version.zip"
$Sha     = "$Zip.sha256"
$BaseUrl = "https://$Bucket.s3.amazonaws.com/$Prefix/$Version-$ReleaseId"

$envChanged = $false

# Windows paths compare case-insensitively, and a trailing '\' is the same dir.
function Test-SamePath([string]$a, [string]$b) {
    [string]::Equals($a.TrimEnd('\'), $b.TrimEnd('\'), [System.StringComparison]::OrdinalIgnoreCase)
}

# Resolve install dir. If ROKOKO_SDK_HOME is unset, default under LOCALAPPDATA.
# It is persisted to the user's environment below, so make it absolute first:
# a relative override would only resolve from the directory we ran in.
$DefaultHome   = Join-Path $Env:LOCALAPPDATA 'Rokoko Device SDK'
$RokokoSdkHome = $Env:ROKOKO_SDK_HOME
if ([string]::IsNullOrWhiteSpace($RokokoSdkHome)) {
    $RokokoSdkHome = $DefaultHome
}
$RokokoSdkHome = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($RokokoSdkHome)

# The install replaces bin\, examples\ and sdk\ in ROKOKO_SDK_HOME wholesale,
# so refuse a folder that already holds something other than an SDK install,
# e.g. a tools folder whose own bin\ would be deleted. An SDK install is
# recognised by our marker file or, for installs that predate it, by the
# Rokoko executables in bin\. The default location is always ours.
$Marker = '.rokoko-device-sdk'
if (-not (Test-SamePath $RokokoSdkHome $DefaultHome) -and
    @(Get-ChildItem -LiteralPath $RokokoSdkHome -Force -ErrorAction SilentlyContinue).Count -gt 0 -and
    -not (Test-Path -LiteralPath (Join-Path $RokokoSdkHome $Marker)) -and
    @(Get-ChildItem -LiteralPath (Join-Path $RokokoSdkHome 'bin') -File -ErrorAction SilentlyContinue |
        Where-Object { $_.Name -like 'rkk_*' -or $_.Name -like 'rokoko-sdk*' }).Count -eq 0) {
    throw "ROKOKO_SDK_HOME ($RokokoSdkHome) is not empty and is not a Rokoko Device SDK install. " +
        "The installer replaces bin\, examples\ and sdk\ there; point ROKOKO_SDK_HOME at a new or empty folder instead."
}

Write-Host "downloading $Zip and $Sha from $BaseUrl/"
Invoke-WebRequest -Uri "$BaseUrl/$Zip" -OutFile $Zip -UseBasicParsing
Invoke-WebRequest -Uri "$BaseUrl/$Sha" -OutFile $Sha -UseBasicParsing

Write-Host "verifying checksum"
# The sidecar is `<hex>  <basename>` (sha256sum format); take the first field.
$expected = (Get-Content -Path $Sha -TotalCount 1).Trim().Split()[0].ToLower()
$actual   = (Get-FileHash -Path $Zip -Algorithm SHA256).Hash.ToLower()
if ($expected -ne $actual) {
    throw "checksum mismatch: expected $expected, got $actual"
}

Write-Host "unpacking $Zip into $RokokoSdkHome"
# Extract to a temp dir, then move the inner `$Name\*` contents into
# ROKOKO_SDK_HOME so `bin/` ends up directly under it. Overlay semantics:
# same-named files are overwritten, unrelated files are left alone.
$Tmp = Join-Path $Env:TEMP ("rkk-install-" + [guid]::NewGuid().ToString("N"))
New-Item -ItemType Directory -Force -Path $Tmp | Out-Null
try {
    Expand-Archive -Path $Zip -DestinationPath $Tmp -Force
    New-Item -ItemType Directory -Force -Path $RokokoSdkHome | Out-Null
    $inner = Join-Path $Tmp $Name
    if (-not (Test-Path $inner)) {
        throw "archive layout unexpected: missing top-level '$Name' directory"
    }

    # The marker file lists the top-level entries the last install created,
    # one per line (it's written at the end of this block). Read it before the
    # new entries go in.
    $markerPath = Join-Path $RokokoSdkHome $Marker
    $oldEntries = @()
    if (Test-Path -LiteralPath $markerPath) {
        $oldEntries = @(Get-Content -LiteralPath $markerPath |
            ForEach-Object { $_.Trim() } | Where-Object { $_ -and -not $_.StartsWith('#') })
    }

    $newEntries = @(Get-ChildItem -Force -LiteralPath $inner | ForEach-Object {
        $dest = Join-Path $RokokoSdkHome $_.Name
        if (Test-Path -LiteralPath $dest) {
            Remove-Item -LiteralPath $dest -Recurse -Force
        }
        Move-Item -LiteralPath $_.FullName -Destination $dest -Force
        $_.Name
    })
    $newEntries += 'VERSION', $Marker

    # Remove entries the last install created that this version no longer
    # ships. The names come from a file on disk, so only plain names are
    # trusted. -contains ignores case, like Windows file names.
    foreach ($old in $oldEntries) {
        if (($old -in @('.', '..')) -or $old.IndexOfAny([char[]]'\/:') -ge 0) { continue }
        if ($newEntries -contains $old) { continue }
        Remove-Item -LiteralPath (Join-Path $RokokoSdkHome $old) -Recurse -Force -ErrorAction SilentlyContinue
    }

    # Record the installed version so an update check can compare it against
    # the published <prefix>/VERSION. Write LF (not CRLF) so the file matches
    # that one exactly: one line + "\n".
    [IO.File]::WriteAllText((Join-Path $RokokoSdkHome 'VERSION'), "$Version`n")

    # Write the marker last, once everything it lists exists. Its presence is
    # what the ROKOKO_SDK_HOME check above looks for; its list tells the next
    # install (or an uninstaller) exactly which top-level entries are ours.
    $markerText = "# Managed by the Rokoko Device SDK installer; it replaces these entries on every install.`n"
    foreach ($entry in $newEntries) { $markerText += "$entry`n" }
    [IO.File]::WriteAllText($markerPath, $markerText)
} finally {
    Remove-Item -LiteralPath $Tmp -Recurse -Force -ErrorAction SilentlyContinue
    Remove-Item -Force $Zip, $Sha -ErrorAction SilentlyContinue
}

# Persist ROKOKO_SDK_HOME and put its bin\ on the user's PATH. User scope only
# -- never Machine scope, to avoid an elevation prompt.
#
# Path is edited in the registry directly: PowerShell has no cmdlet for
# persistent variables, and [Environment]::SetEnvironmentVariable reads Path
# with its %VAR% references already expanded and writes it back as REG_SZ,
# which hard-codes them and stops Windows expanding any added later.
#
# The entry we add is the literal `%ROKOKO_SDK_HOME%\bin`. Windows sets user
# REG_SZ variables before it expands user REG_EXPAND_SZ ones such as Path, so
# the reference resolves as long as ROKOKO_SDK_HOME is REG_SZ. Path is then
# written once, and moving the install only changes ROKOKO_SDK_HOME.
$BinDir    = Join-Path $RokokoSdkHome 'bin'
$PathEntry = '%ROKOKO_SDK_HOME%\bin'
$noExpand  = [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames
$envKey    = [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey('Environment')
try {
    $savedHome = $envKey.GetValue('ROKOKO_SDK_HOME', $null, $noExpand)
    $homeIsCurrent = $savedHome -and
        $envKey.GetValueKind('ROKOKO_SDK_HOME') -eq [Microsoft.Win32.RegistryValueKind]::String -and
        (Test-SamePath $savedHome $RokokoSdkHome)

    # Earlier installers added the expanded bin dir instead. Swap the first
    # such entry (for this install, or the one we're moving from) for
    # $PathEntry in place, keeping the user's ordering, and drop the rest.
    # Every other entry is written back exactly as it was.
    $legacyBins = @($BinDir)
    if ($savedHome) {
        $legacyBins += [Environment]::ExpandEnvironmentVariables($savedHome).TrimEnd('\') + '\bin'
    }
    $rawPath = [string]$envKey.GetValue('Path', '', $noExpand)
    $entries = New-Object System.Collections.Generic.List[string]
    $placed  = $false
    foreach ($e in $rawPath.Split(';')) {
        if (-not $e.Trim()) { continue }
        $expanded = [Environment]::ExpandEnvironmentVariables($e.Trim())
        $isOurs = (Test-SamePath $e.Trim() $PathEntry) -or
            @($legacyBins | Where-Object { Test-SamePath $expanded $_ }).Count -gt 0
        if (-not $isOurs) {
            $entries.Add($e)
        } elseif (-not $placed) {
            $entries.Add($PathEntry)
            $placed = $true
        }
    }
    if (-not $placed) {
        $entries.Add($PathEntry)
    }
    $newPath = $entries -join ';'
    $pathIsCurrent = $newPath -ceq $rawPath -and
        $envKey.GetValueKind('Path') -eq [Microsoft.Win32.RegistryValueKind]::ExpandString
    if (-not $pathIsCurrent) {
        $envKey.SetValue('Path', $newPath, [Microsoft.Win32.RegistryValueKind]::ExpandString)
    }
} finally {
    $envKey.Close()
}
if (-not ($homeIsCurrent -and $pathIsCurrent)) {
    # Writes ROKOKO_SDK_HOME as REG_SZ, overwriting any earlier value, and
    # broadcasts WM_SETTINGCHANGE so new terminals see it and the Path above.
    [Environment]::SetEnvironmentVariable('ROKOKO_SDK_HOME', $RokokoSdkHome, 'User')
    $envChanged = $true
}

# The registry changes only reach new processes; update this session too.
$Env:ROKOKO_SDK_HOME = $RokokoSdkHome
if (@($Env:PATH.Split(';') | Where-Object { Test-SamePath $_.Trim() $BinDir }).Count -eq 0) {
    $Env:PATH = "$BinDir;$Env:PATH"
}

Write-Host "installed $Name $Version into $RokokoSdkHome"
if ($envChanged) {
    Write-Host "environment updated; you may need to restart your terminal for changes to take effect."
}
